template <typename T>
void handle_type(T&& value) {
    // Prefer templates over void* and static_cast
    // Avoids: handle_type((void*)ptr); T* t = static_cast<T*>(ptr);
    // ... use value directly
}
int i = 5;
handle_type(i);


void print_value(int i) {}
void print_value(double d) {}

long l_val = 10L;
float f_val = 2.5f;

// Prefer overloading over explicit numeric casts
// Compiler handles implicit conversion/promotion
print_value(l_val);
print_value(f_val);


class ProxyValue {
    int data_;
public:
    ProxyValue(int d) : data_(d) {}

    // Avoids: static_cast<int>(proxy_obj)
    operator int() const {
        return data_;
    }
};
ProxyValue p(100);
int x = p;


class CachedResult {
    mutable int access_count = 0;
    int compute() const {
        // Use mutable instead of const_cast
        access_count++;
        return 1;
    }
public:
    int get_data() const {
        return compute();
    }
};
